         data-moderator-game-status-value="<%= @state[:status] %>"
         data-moderator-game-game-question-id-value="<%= @state[:game_question_id].to_i %>"
         data-moderator-game-version-value="<%= @state[:state_version] %>">
  <div class="screen">
    <div class="screen__top">
      <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
      <span data-moderator-game-target="topTitle"><%= (@state[:status] == "question_open" || @state[:status] == "question_closed") ? @state[:quiz_title] : "" %></span>
    </div>

    <div class="screen__body" data-moderator-game-target="stage">
      <% if @state[:status] == "lobby" %>
        <div class="lobby">
          <div>
            <h1 class="lobby__title"><%= @state[:quiz_title] %></h1>
            <div class="lobby__join">Join at</div>
            <div class="lobby__url"><%= @join_url %></div>
