  applyState(state, { authoritative = false } = {}) {
    if (!state) return
    if (state.state_version && state.state_version < this.versionValue) return

    if (authoritative) {
      if (state.joined !== undefined) this.joinedValue = Boolean(state.joined)
      if (state.player_name) this.playerNameValue = state.player_name
    }

    if (!this.joinedValue) {
      if (state.state_version && state.state_version > this.versionValue) {
        this.versionValue = state.state_version
      }
      if (state.status === "finished" && this.statusValue !== "finished") {
        this.statusValue = "finished"
        this.bodyTarget.classList.remove("play__body--top")
        this.renderFinishedUnjoined()
      }
      return
    }

    // Joined player receiving public-stream "finished" message (without personal place/points):
    // wait briefly for the private-stream personal payload, or fetch /state if needed.
    if (state.status === "finished" && state.place === undefined) {
      if (this.finishedFallbackTimer) clearTimeout(this.finishedFallbackTimer)
      const targetVersion = state.state_version || 0
      this.finishedFallbackTimer = setTimeout(() => {
        if (this.versionValue < targetVersion || this.statusValue !== "finished") {
          this.fetchState(false)
        }
      }, 150)
      return
    }

    if (this.finishedFallbackTimer) {
      clearTimeout(this.finishedFallbackTimer)
      this.finishedFallbackTimer = null
    }

    if (state.state_version && state.state_version > this.versionValue) {
      this.versionValue = state.state_version
    }

    if (state.status === "finished") {
      this.statusValue = "finished"
      this.gameQuestionIdValue = 0
      if (this.hasHeaderInfoTarget) {
